/* BUILD40: five explicit exterior recipes; only entrance floors are walkable. */
(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.Engineering40=api;})(this,()=>{
function prepare(data,nav,spec){if(nav.engineering40)return nav.engineering40;const ids=new Set(spec.models.map(m=>m.id));
 for(const m of spec.models){const b=data.buildings.find(b=>b.id===m.id);if(!b)throw Error('Missing BUILD40 owner '+m.id);b.landmark30=true;b.engineering40=true;b.base=m.fit.datum;b.top=m.top;b.heightRecord={groundDatum:b.base,roofElevation:b.top,structureHeight:b.top-b.base,note:'BUILD40 photo/design estimate; separate local datum'};delete b.renderParts;delete b.collisionPolygons;}
 // The owning render loop bypasses the old review/official generators entirely.
 nav.landmarks30.surfaces=nav.landmarks30.surfaces.filter(q=>!ids.has(q.building));nav.landmarks30.volumes=nav.landmarks30.volumes.filter(q=>!ids.has(q.building));
 nav.landmarks30.surfaces.push(...spec.models.flatMap(m=>m.surfaces));nav.landmarks30.volumes.push(...spec.models.flatMap(m=>m.volumes));nav.engineering40=spec;return spec;
}
function build(B,scene,spec){const colors={panel:'#dddeda',steel:'#eeeae2',glass:'#77a5aa',glassBlue:'#719eae',door:'#536f73',frame:'#435b60',spandrel:'#86b7b3',dark:'#4a5054',roof:'#a6afb3',ribbed:'#bec6ca',stone:'#babeb9',rail:'#7e9295',metal:'#aebbc1',service:'#a7b1b6'},materials={};
 for(const [k,c]of Object.entries(colors)){const m=new B.StandardMaterial('engineering40-'+k,scene);m.diffuseColor=B.Color3.FromHexString(c);m.specularColor=B.Color3.FromHexString(/glass|door/.test(k)?'#344c50':'#131719');m.specularPower=64;m.backFaceCulling=false;m.twoSidedLighting=true;m.metadata={gwanjeong37:true,engineering40:true};
 if(['panel','ribbed','dark','stone'].includes(k)){const t=new B.DynamicTexture('engineering40-'+k+'-finish',{width:512,height:512},scene,false),ctx=t.getContext();ctx.fillStyle=c;ctx.fillRect(0,0,512,512);let seed=40;for(let i=0;i<16000;i++){seed=(1664525*seed+1013904223)>>>0;const x=seed%512;seed=(1664525*seed+1013904223)>>>0;const y=seed%512;ctx.fillStyle=i%2?'#ffffff07':'#00000006';ctx.fillRect(x,y,1,1);}ctx.strokeStyle=k==='dark'?'#758087':'#929c9e';ctx.lineWidth=k==='ribbed'?1.8:.65;ctx.beginPath();if(k==='ribbed'){for(let x=0;x<512;x+=12){ctx.moveTo(x,0);ctx.lineTo(x,512);}}else{ctx.moveTo(0,0);ctx.lineTo(512,0);ctx.moveTo(0,256);ctx.lineTo(512,256);ctx.moveTo(0,0);ctx.lineTo(0,512);}ctx.stroke();t.update(false);t.uScale=t.vScale=k==='stone'?1/1.5:1/3.2;m.diffuseTexture=t;m.diffuseColor=B.Color3.White();}materials[k]=m;}
 const stats=[];for(const model of spec.models){let count=0,tri=0;for(const [k,g]of Object.entries(model.groups)){if(!g.indices.length)continue;const m=new B.Mesh('building-'+model.id+'-engineering40-'+k,scene),vd=new B.VertexData();vd.positions=g.positions;vd.indices=g.indices;vd.uvs=g.uvs;vd.normals=[];B.VertexData.ComputeNormals(g.positions,g.indices,vd.normals);vd.applyToMesh(m);m.material=materials[k];m.metadata={facilityId:model.id,engineering40:true,category30:'building'};m.isPickable=true;m.freezeWorldMatrix();count++;tri+=g.indices.length/3;}stats.push({number:model.number,meshes:count,triangles:tri});}
 scene.metadata={...scene.metadata,engineering40:stats};return stats;
}
function treeHit(spec,x,z,r,lo=-Infinity,hi=Infinity){if(!spec)return false;for(const m of spec.models){for(const q of m.volumes){if(q.lo>hi||q.hi<lo)continue;let inside=false;for(let i=0,j=q.p.length-1;i<q.p.length;j=i++){const a=q.p[i],b=q.p[j];if((a[1]>z)!=(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])inside=!inside;const dx=b[0]-a[0],dz=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz||1)));if(Math.hypot(x-a[0]-dx*t,z-a[1]-dz*t)<r)return true;}if(inside)return true;}const f=m.fit,dx=x-f.origin[0],dz=z-f.origin[1],u=(dx*f.u[0]+dz*f.u[1])/f.scale,v=(dx*f.v[0]+dz*f.v[1])/f.scale;for(const e of m.entries){if(Math.abs(u-e.x)<7+r/f.scale&&v>e.start-r/f.scale&&v<e.front+2)return true;}}
 return false;}
return{prepare,build,treeHit};});
